let mappa: Map<string, string> | null = null;

function chiave(nome: string): string {
  return nome
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z]/g, "");
}

/** Il codice catastale del comune, o null se non è nell'elenco. */
export function codiceCatastale(nome: string, sigla: string): string | null {
  if (!mappa) {
    mappa = new Map();
    for (const r of RIGHE.split(";")) {
      const [k, codice] = r.split("=");
      mappa.set(k, codice);
    }
  }
  return mappa.get(`${chiave(nome)}|${sigla.toUpperCase()}`) ?? null;
}
